CREATE TABLE public.operation_funnels (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80), origin text NOT NULL CHECK(length(origin)<=250), active boolean NOT NULL DEFAULT true, consent_required boolean NOT NULL DEFAULT true, steps jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.operation_funnels TO authenticated;
GRANT ALL ON public.operation_funnels TO service_role;
ALTER TABLE public.operation_funnels ENABLE ROW LEVEL SECURITY;
CREATE POLICY funnel_owner ON public.operation_funnels FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.funnel_sessions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), funnel_id uuid NOT NULL REFERENCES public.operation_funnels(id), token_hash text NOT NULL, visitor_id uuid NOT NULL, source text NOT NULL DEFAULT 'Direto', campaign text NOT NULL DEFAULT '', medium text NOT NULL DEFAULT '', device text NOT NULL DEFAULT 'desktop', created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.funnel_sessions TO authenticated;
GRANT ALL ON public.funnel_sessions TO service_role;
ALTER TABLE public.funnel_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY session_owner ON public.funnel_sessions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.operation_funnels f WHERE f.id=funnel_id AND f.user_id=auth.uid()));
CREATE TABLE public.funnel_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES public.funnel_sessions(id), event_id uuid NOT NULL UNIQUE, event text NOT NULL CHECK(event IN ('page_view','page_complete','click','scroll','engagement','form_start','form_submit','quiz_start','quiz_step','quiz_complete','vsl_start','vsl_progress','vsl_complete','checkout_click')), path text NOT NULL CHECK(length(path)<=300), label text NOT NULL DEFAULT '' CHECK(length(label)<=80), value integer NOT NULL DEFAULT 0 CHECK(value BETWEEN 0 AND 86400), created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.funnel_events TO authenticated;
GRANT ALL ON public.funnel_events TO service_role;
ALTER TABLE public.funnel_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_owner ON public.funnel_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.funnel_sessions s JOIN public.operation_funnels f ON f.id=s.funnel_id WHERE s.id=session_id AND f.user_id=auth.uid()));
CREATE INDEX funnel_sessions_time ON public.funnel_sessions(funnel_id,created_at DESC);
CREATE INDEX funnel_events_session ON public.funnel_events(session_id,created_at DESC);
ALTER TABLE public.checkout_sessions ADD COLUMN funnel_session_id uuid REFERENCES public.funnel_sessions(id);
CREATE OR REPLACE FUNCTION public.get_external_funnel_report(p_funnel uuid,p_hours integer DEFAULT 24) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
WITH sessions AS (SELECT s.* FROM public.funnel_sessions s JOIN public.operation_funnels f ON f.id=s.funnel_id WHERE f.user_id=auth.uid() AND f.id=p_funnel AND s.created_at>=now()-make_interval(hours=>LEAST(GREATEST(p_hours,1),720))), events AS (SELECT e.* FROM public.funnel_events e JOIN sessions s ON s.id=e.session_id), outcomes AS (SELECT DISTINCT s.id, EXISTS(SELECT 1 FROM public.checkout_sessions c WHERE c.funnel_session_id=s.id AND c.user_id=auth.uid()) checkout, EXISTS(SELECT 1 FROM public.checkout_sessions c JOIN public.transactions t ON t.metadata->'tracking'->>'operation_session_id'=c.id::text WHERE c.funnel_session_id=s.id AND c.user_id=auth.uid() AND t.user_id=auth.uid() AND NOT t.is_test AND t.status='paid') paid FROM sessions s), totals AS (SELECT count(*) sessions,count(DISTINCT visitor_id) visitors,count(*) FILTER(WHERE last_seen_at>=now()-interval '5 minutes') active FROM sessions), event_counts AS (SELECT event,count(*) events,count(DISTINCT session_id) leads FROM events GROUP BY event), pages AS (SELECT path,count(*) FILTER(WHERE event='page_view') views,count(DISTINCT session_id) FILTER(WHERE event='page_view') leads,count(DISTINCT session_id) FILTER(WHERE event='page_complete') completed,COALESCE(sum(value) FILTER(WHERE event='engagement'),0) seconds FROM events GROUP BY path ORDER BY count(*) FILTER(WHERE event='page_view') DESC LIMIT 50), sources AS (SELECT source,campaign,medium,count(*) sessions,count(DISTINCT visitor_id) visitors FROM sessions GROUP BY source,campaign,medium ORDER BY count(*) DESC LIMIT 30), hourly AS (SELECT h.ts,count(s.id) leads FROM generate_series(date_trunc('hour',now())-interval '23 hours',date_trunc('hour',now()),interval '1 hour') h(ts) LEFT JOIN sessions s ON s.created_at>=h.ts AND s.created_at<h.ts+interval '1 hour' GROUP BY h.ts ORDER BY h.ts), media AS (SELECT label,event,value,count(DISTINCT session_id) leads FROM events WHERE event LIKE 'vsl_%' OR event LIKE 'quiz_%' GROUP BY label,event,value), recent AS (SELECT e.*,s.device,s.source FROM events e JOIN sessions s ON s.id=e.session_id ORDER BY e.created_at DESC LIMIT 50), journeys AS (SELECT s.id,s.source,s.device,(SELECT jsonb_agg(jsonb_build_object('path',e.path,'at',e.created_at) ORDER BY e.created_at) FROM events e WHERE e.session_id=s.id AND e.event='page_view') pages FROM sessions s ORDER BY s.created_at DESC LIMIT 20)
SELECT jsonb_build_object('totals',(SELECT to_jsonb(totals) FROM totals),'counts',COALESCE((SELECT jsonb_agg(event_counts) FROM event_counts),'[]'),'pages',COALESCE((SELECT jsonb_agg(pages) FROM pages),'[]'),'sources',COALESCE((SELECT jsonb_agg(sources) FROM sources),'[]'),'hourly',COALESCE((SELECT jsonb_agg(hourly) FROM hourly),'[]'),'media',COALESCE((SELECT jsonb_agg(media) FROM media),'[]'),'recent',COALESCE((SELECT jsonb_agg(recent) FROM recent),'[]'),'journeys',COALESCE((SELECT jsonb_agg(journeys) FROM journeys),'[]'),'checkout',(SELECT count(*) FROM outcomes WHERE checkout),'paid',(SELECT count(*) FROM outcomes WHERE paid));
$$;
REVOKE ALL ON FUNCTION public.get_external_funnel_report(uuid,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_external_funnel_report(uuid,integer) TO authenticated;